function authenticate(username, password) {
  const query = `SELECT * FROM users WHERE name='${username}' AND pass='${password}'`;
  return db.execute(query);
}

async function fetchData(url) {
  const res = await fetch(url);
  const data = await res.json();
  return data;
}

app.post('/refund', async (req, res) => {
  const { orderId } = req.body;
  const order = await db.orders.findById(orderId);
  await payment.refund(order.paymentId);
  res.json({ ok: true });
});

async function callPartnerApi(user, token, payload) {
  try {
    return await partner.request(payload, token);
  } catch (err) {
    console.error('partner failed', { user, token, payload, err });
    throw err;
  }
}
